<?php
declare(strict_types=1);
namespace Brebo\Office\Finance\Center;
require_once __DIR__.'/Report.php';
final class View {
  private static function e(mixed $v): string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
  private static function input(string $name,string $label,string $value='',string $type='text',bool $required=true): string{return '<label>'.self::e($label).'<input name="'.self::e($name).'" type="'.$type.'" value="'.self::e($value).'"'.($required?' required':'').'></label>';}
  private static function start(string $action,string $csrf,array $values=[]): string{$h='<form method="post"><input type="hidden" name="csrf" value="'.self::e($csrf).'"><input type="hidden" name="action" value="'.self::e($action).'">';foreach($values as $k=>$v)$h.='<input type="hidden" name="'.self::e($k).'" value="'.self::e($v).'">';return $h;}
  private static function end(string $caption): string{return '<label class="check"><input type="checkbox" name="confirmed" value="yes" required> Gegevens en bron gecontroleerd</label><button>'.self::e($caption).'</button></form>';}
  private static function projects(array $projects): string{$h='<label>Project<select name="project_id"><option value="">Algemeen / overhead</option>';foreach($projects as $p)$h.='<option value="'.(int)$p['office_project_id'].'">'.self::e($p['title']).'</option>';return $h.'</select></label>';}
  private static function payment(string $type,array $p,string $csrf,string $today): string {
    return '<details><summary>Gecontroleerde betaling registreren</summary><p>Dit registreert een werkelijk ontvangen of betaald bedrag uit de bankadministratie.</p>'.self::start('payment',$csrf,['entity_type'=>$type,'id'=>$p['id'],'revision'=>$p['revision']]).self::input('amount','Bedrag').self::input('date','Betaaldatum',$today,'date').self::input('reference','Unieke banktransactiereferentie').'<label>Rekeningsoort<select name="bucket"><option value="regular">Gewone rekening</option><option value="g">G-rekening</option></select></label>'.self::end('Betaling registreren').'</details>';
  }
  public static function render(array $r,array $projects,string $csrf,bool $write,string $tab,string $commandKey,string $error='',array $posted=[]): string {
    $e=self::e(...);$money=Amounts::money(...);$today=$r['as_of'];$tabs=['overview'=>'Overzicht','purchases'=>'Inkoop & kosten','hours'=>'Uren & kostprijzen','payments'=>'Betalingen','planning'=>'Liquiditeit','review'=>'Controle','customers'=>'Project & klant'];if(!isset($tabs[$tab]))$tab='overview';
    $h='<!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Financiële administratie · BREBO Office</title><style>'.self::css().'</style></head><body><main><nav><a href="/office-test/finance">Finance-overzicht</a><a href="/office-test/finance/verkoop">Verkoopfacturen</a><a href="/office-test/finance/betaalcentrum">Betaalcentrum</a></nav><header><p class="eyebrow">BREBO Office · FinanceCenter</p><h1>Financiële administratie</h1><p>Boekingen, uren en betalingen tot en met '.$e($today).', binnen jouw toegangsrechten.</p></header><nav aria-label="Administratie">';foreach($tabs as $key=>$label)$h.='<a'.($key===$tab?' aria-current="page"':'').' href="?tab='.$key.'">'.$label.'</a>';$h.='</nav>';
    if($error!==''){$h.='<section class="error" role="alert">'.$e($error).'</section>';if($posted){$h.='<details open><summary>Niet opgeslagen invoer</summary><dl>';foreach($posted as $key=>$v)if(!in_array($key,['csrf','command_key'],true))$h.='<dt>'.$e($key).'</dt><dd>'.$e(is_scalar($v)?$v:json_encode($v,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)).'</dd>';$h.='</dl><p>De bron is niet aangepast. Controleer de invoer in het betreffende formulier.</p></details>';}}
    if($tab==='overview'){
      $h.='<div class="metrics">';foreach(['revenue_cents'=>'Omzet excl. btw','direct_cents'=>'Directe kosten excl. btw','labor_cents'=>'Arbeidskosten','overhead_cents'=>'Overhead excl. btw','gross_margin_cents'=>'Brutomarge','operating_result_cents'=>'Bedrijfsresultaat'] as $key=>$label)$h.='<section><h2>'.$label.'</h2><strong>'.($r[$key]===null?'Nog te bevestigen':$money((int)$r[$key])).'</strong></section>';$h.='</div><section><h2>Grondslag</h2><p>Managementoverzicht van dit kalenderjaar: verzonden Office-facturen min geboekte directe kosten, gewaardeerde goedgekeurde uren en overhead. Btw telt niet als opbrengst of kosten.</p><p>Inkoopconcepten te boeken: '.(int)$r['pending_purchase_count'].'. Goedgekeurde uren te waarderen: '.(int)$r['unpriced_hours_count'].'.</p><p>'.($r['cost_review_ready']?'Kostengrondslag bevestigd voor deze stand.':'Bevestig de volledige kostengrondslag bij Controle om marge en resultaat te tonen.').'</p></section>';
      $h.=self::forecast($r);
    }
    if($tab==='purchases'){
      $h.='<section><h2>Inkoopconcepten</h2><p><a href="/office-test/finance/nieuw">Nieuwe inkoopfactuur</a>. Controleer leverancier, factuurnummer, datum, bedragen en projectverdeling voordat je boekt.</p>';
      foreach($r['purchase_choices'] as $p)$h.='<p><a href="?tab=purchases&amp;purchase='.(int)$p['id'].'">'.$e($p['supplier_name'].' · '.$p['invoice_number']).'</a> · '.$e($p['invoice_date']).' · '.$money(Amounts::cents($p['total'])).'</p>';
      if(!$r['purchase_choices'])$h.='<p>Geen inkoopconcepten met volledig toegankelijke projectregels.</p>';
      $h.='</section>';
      if(isset($r['purchase_preview'])){$p=$r['purchase_preview'];$h.='<section><h2>Boekingscontrole · '.$e($p['supplier_name'].' / '.$p['invoice_number']).'</h2><p>Factuurdatum '.$e($p['invoice_date']).' · vervaldatum '.$e($p['due_date']).' · '.$e($p['currency']).'</p><table><thead><tr><th>Omschrijving</th><th>Project</th><th>Excl. btw</th><th>Btw</th></tr></thead><tbody>';foreach($p['lines'] as $line)$h.='<tr><td>'.$e($line['description']).'</td><td>'.(int)$line['office_project_id'].'</td><td>'.$e($line['net_amount']).'</td><td>'.$e($line['vat_amount']).'</td></tr>';$h.='</tbody></table><p>Totaal '.$e($p['total']).' · <a href="/office-test/finance/dossier?id='.(int)$p['id'].'">Concept aanpassen</a></p>';if($write)$h.=self::start('book_purchase',$csrf,['id'=>$p['id'],'source_hash'=>Amounts::hash($p)]).self::input('g_amount','Naar G-rekening van leverancier','0').self::end('Inkoopfactuur definitief boeken');$h.='</section>';}
      if($write)$h.='<section><h2>Overige kosten boeken</h2><p>Gebruik een brondocument. Waardeer OnSite-uren bij Uren; boek die arbeid hier niet opnieuw. Een niet-liquide kostenpost (bijvoorbeeld afschrijving) veroorzaakt geen betaling. Plan loon- en belastingbetalingen afzonderlijk bij Liquiditeit.</p>'.self::start('manual',$csrf,['command_key'=>$commandKey]).self::projects($projects).'<label>Kostensoort<select name="category"><option value="direct">Directe projectkosten</option><option value="overhead">Overhead</option><option value="labor">Arbeid buiten gewaardeerde OnSite-uren</option></select></label>'.self::input('date','Boekingsdatum',$today,'date').self::input('net','Kosten excl. btw').self::input('vat','Btw-bedrag','0').self::input('description','Omschrijving').self::input('reference','Referentie brondocument').'<label class="check"><input type="checkbox" name="cash_due" value="yes"> Deze kostenpost moet nog worden betaald</label>'.self::input('due_date','Vervaldatum indien nog te betalen','','date',false).self::end('Kosten boeken').'</section>';
      $h.='<section><h2>Boekingsregister</h2><table><thead><tr><th>Bron</th><th>Datum</th><th>Excl. btw</th><th>Totaal</th><th>Status</th></tr></thead><tbody>';foreach($r['postings'] as $p)$h.='<tr><td><a href="?tab=purchases&amp;posting='.(int)$p['id'].'">'.$e($p['document_ref']).'</a></td><td>'.$e($p['booking_date']).'</td><td>'.$money((int)$p['net_cents']).'</td><td>'.$money((int)$p['gross_cents']).'</td><td>'.$e($p['status']==='booked'?'Geboekt':'Tegengeboekt').'</td></tr>';$h.='</tbody></table></section>';
      if(isset($r['posting_preview'])){$p=$r['posting_preview'];$h.='<section><h2>Boeking #'.(int)$p['id'].'</h2><p>'.$e($p['document_ref']).' · '.$e($p['booking_date']).' · '.$money((int)$p['gross_cents']).'</p><dl>';foreach($p['lines'] as $line)$h.='<dt>'.$e($line['description']).' · '.$e($line['category']).'</dt><dd>'.$money((int)$line['net_cents']).' excl. btw</dd>';$h.='</dl>';if($write&&$p['status']==='booked'&&(int)$p['paid_cents']===0)$h.='<details><summary>Onbetaalde boeking corrigeren</summary><p>De oorspronkelijke boeking en reden blijven bewaard. Een inkoopfactuur wordt weer concept.</p>'.self::start('reverse',$csrf,['id'=>$p['id'],'revision'=>$p['revision']]).self::input('reason','Reden correctie').self::end('Tegenboeken').'</details>';$h.='</section>';}
    }
    if($tab==='hours'){
      $h.='<section><h2>Goedgekeurde uren waarderen</h2><p>Alleen goedgekeurde OnSite-uren met een bevestigde kostprijs op de werkdatum worden geboekt. Een waardering gebruikt een vaste bronkopie en wordt één keer geboekt.</p><table><thead><tr><th>Bron</th><th>Medewerker</th><th>Project</th><th>Goedgekeurde uren</th><th></th></tr></thead><tbody>';foreach($r['hours'] as $p){$h.='<tr><td>#'.(int)$p['id'].' · '.$e($p['worked_at']).'</td><td>#'.(int)$p['person_id'].'</td><td>'.$e($p['project_id']).'</td><td>'.number_format((int)$p['reviewed_seconds']/3600,2,',','.').'</td><td>';if($write)$h.=self::start('value_hours',$csrf,['id'=>$p['id'],'revision'=>$p['revision']]).self::end('Uren waarderen');$h.='</td></tr>';}$h.='</tbody></table></section>';
      if($write)$h.='<section><h2>Bevestigde kostprijs per medewerker</h2><p>Voer de onderbouwde kostprijs per uur in. Dit is geen verkoopuurtarief. Bestaande waarderingen wijzigen niet met een nieuw tarief.</p>'.self::start('rate',$csrf).self::input('person_id','Medewerkernummer','','number').self::input('effective_from','Geldig vanaf',$today,'date').self::input('rate','Kostprijs per uur').self::input('reference','Onderbouwing / referentie').self::end('Kostprijs vastleggen').'</section>';
    }
    if($tab==='payments'){
      $h.='<section><h2>Betalingen registreren</h2><p>Registreer uitsluitend geverifieerde banktransacties met een unieke bankreferentie. De registratie verstuurt geen betaalopdracht. Bankmutaties zijn afzonderlijk beschikbaar in <a href="/office-test/finance/betaalcentrum">Betaalcentrum</a>.</p></section><div class="columns"><section><h2>Te ontvangen verkoopfacturen</h2>';foreach($r['sales'] as $p)if($p['status']==='sent'&&(int)$p['paid_cents']<(int)$p['gross_cents']){$h.='<h3>'.$e($p['invoice_number']).' · '.$money((int)$p['gross_cents']-(int)$p['paid_cents']).'</h3>';if($write)$h.=self::payment('sale',$p,$csrf,$today);}$h.='</section><section><h2>Te betalen boekingen</h2>';foreach($r['postings'] as $p)if($p['status']==='booked'&&(int)$p['cash_due']===1&&(int)$p['paid_cents']<(int)$p['gross_cents']){$h.='<h3>'.$e($p['document_ref']).' · '.$money((int)$p['gross_cents']-(int)$p['paid_cents']).'</h3>';if($write)$h.=self::payment('expense',$p,$csrf,$today);}$h.='</section></div>';
    }
    if($tab==='planning'){
      $h.=self::forecast($r);$h.='<section><h2>Aanvullende betaalplanning</h2><p>Neem bijvoorbeeld loon, belastingen, huur of bevestigde ontvangsten op. Boekingen en verzonden facturen staan al in de prognose: neem die hier niet nogmaals op.</p>';
      foreach($r['plans'] as $p){$h.='<details><summary>'.$e($p['description']).' · '.$e($p['due_date']).' · '.$money((int)$p['amount_cents']-(int)$p['paid_cents']).' · '.$e($p['status']).'</summary><p>'.$e($p['evidence_reference']).' · '.$e($p['direction']==='in'?'Ontvangst':'Betaling').' · '.$e($p['account_bucket']==='g'?'G-rekening':'Gewone rekening').'</p>';if($write&&$p['status']==='planned'){$h.=self::start('settle_plan',$csrf,['id'=>$p['id']]).self::input('amount','Werkelijk betaald / ontvangen').self::input('date','Bankdatum',$today,'date').self::input('reference','Unieke bankreferentie').self::end('Werkelijke betaling registreren');$h.=self::start('cancel_plan',$csrf,['id'=>$p['id']]).self::input('reason','Reden vervallen resterende planning').self::end('Resterende planning laten vervallen');}$h.='</details>';}
      if($write)$h.='<details><summary>Planning toevoegen</summary>'.self::start('plan',$csrf).self::projects($projects).'<label>Richting<select name="direction"><option value="out">Uitgaand</option><option value="in">Inkomend</option></select></label><label>Rekeningsoort<select name="bucket"><option value="regular">Gewone rekening</option><option value="g">G-rekening</option></select></label>'.self::input('amount','Bedrag incl. btw').self::input('due_date','Verwachte bankdatum',$today,'date').self::input('description','Omschrijving').self::input('reference','Unieke bronreferentie').self::end('Aan betaalplanning toevoegen').'</details>';$h.='</section>';
      if($write&&!empty($r['bank_access'])){$h.='<section><h2>Bevestigde beginsaldi</h2><p>Vul de eindsaldi per rekening op de gekozen datum in. Neem alle gewone rekeningen en G-rekeningen op. Nieuwe bevestiging vervangt de gebruikte stand; eerdere bevestigingen blijven bewaard. Moneybird levert hier geen banksaldo.</p>'.self::start('opening',$csrf).self::input('balance_date','Datum eindsaldi',$today,'date').self::input('reference','Bron bankafschrift / saldoverificatie').'<p>Gebruik één regel per rekening: rekeningreferentie | regular of g | saldo. Een roodstand mag negatief zijn. Laat ontbrekende saldi niet als nul staan.</p><label>Rekeningen<textarea name="accounts" required rows="5" placeholder="Rekeningreferentie | regular | bevestigd saldo"></textarea></label>'.self::end('Eindsaldi bevestigen').'</section>';}
    }
    if($tab==='customers'){
      $h.='<section><h2>Factuurdebiteur per project</h2><p>Koppel expliciet de factuurdebiteur. Bij projectkeuze worden het factuuradres en de unieke primaire contactpersoon ingevuld. Wijzigingen gelden voor nieuwe of opnieuw opgeslagen concepten; verzonden facturen behouden hun klantgegevens.</p>';
      foreach($projects as $project){$id=(int)$project['office_project_id'];$parties=$r['project_parties'][$id]??[];$relation=count($parties)===1?(int)$parties[0]['relation_id']:0;$h.='<details><summary>'.$e($project['title']).'</summary>';
        if($write){$h.=self::start('bind_debtor',$csrf,['project_id'=>$id,'source_hash'=>Amounts::hash($parties)]).'<label>Factuurdebiteur<select name="relation_id" required><option value="">Kies een actieve relatie</option>';foreach($r['customers']??[] as $c)$h.='<option value="'.(int)$c['id'].'"'.((int)$c['id']===$relation?' selected':'').'>'.$e($c['display_name']).'</option>';$h.='</select></label>'.self::end('Factuurdebiteur bevestigen');}$h.='</details>';
      }$h.='<p>Factuuradres, factuur e-mail, offerte e-mail en algemene e-mail zijn te beheren bij de betreffende CRM-relatie.</p></section>';
    }
    if($tab==='review'){
      $h.='<section><h2>Administratiecontrole</h2>'.(!empty($r['valuation_stale'])?'<p class="error">Gewaardeerde uren zijn achteraf gewijzigd. Boek de oude waardering tegen en waardeer de actuele goedkeuring opnieuw.</p>':'').'<p>Marge en resultaat worden pas berekend wanneer de kostengrondslag compleet is bevestigd. Liquiditeit vereist bovendien bevestigde beginsaldi, een volledige financiële scope en een complete betaalplanning. Een gewijzigde bron maakt deze bevestiging ongeldig.</p><p>Openstaande inkoopconcepten: '.(int)$r['pending_purchase_count'].' · niet gewaardeerde goedgekeurde uren: '.(int)$r['unpriced_hours_count'].'.</p>';
      if($write){$h.=self::start('review',$csrf,['source_hash'=>$r['source_hash']]);foreach(['costs'=>'Alle inkoop en directe kosten in dit kalenderjaar zijn geboekt','hours'=>'Alle goedgekeurde uren in dit kalenderjaar zijn gewaardeerd','overhead'=>'Alle overheadkosten in dit kalenderjaar zijn geboekt','cash'=>'Alle toekomstige ontvangsten en betalingen zijn opgenomen zonder dubbeltellingen'] as $k=>$label)$h.='<label class="check"><input type="checkbox" name="'.$k.'_complete" value="yes"> '.$e($label).'</label>';$h.=self::input('reference','Controle / onderbouwing').self::end('Gecontroleerde stand bevestigen');}$h.='</section>';
    }
    return $h.'</main></body></html>';
  }
  private static function forecast(array $r): string{$e=self::e(...);$money=Amounts::money(...);$h='<section><h2>Liquiditeitsprognose</h2>';if(!$r['forecast']){$h.='<ul>';foreach(array_unique($r['forecast_reasons']) as $reason)$h.='<li>'.$e($reason).'</li>';$h.='</ul><a href="?tab=planning">Saldo en betaalplanning aanvullen</a>';}else{$h.='<p>Uitgaande van de bevestigde eindsaldi op '.$e($r['forecast']['balance_date']).', geregistreerde bankbewegingen daarna en de bevestigde betaalplanning. Gewone rekening en G-rekening blijven gescheiden.</p><table><thead><tr><th>Horizon</th><th>Ontvangsten</th><th>Betalingen</th><th>Gewoon beschikbaar</th><th>G-rekening</th></tr></thead><tbody>';foreach($r['forecast']['horizons'] as $days=>$f)$h.='<tr><td>'.(int)$days.' dagen</td><td>'.$money(array_sum($f['incoming'])).'</td><td>'.$money(array_sum($f['outgoing'])).'</td><td>'.$money($f['ending']['regular']).'</td><td>'.$money($f['ending']['g']).'</td></tr>';$h.='</tbody></table>'; }return $h.'</section>';}
  private static function css(): string{return '*{box-sizing:border-box}body{margin:0;background:#f3f5f8;color:#243242;font:14px/1.55 system-ui}main{max-width:1300px;margin:auto;padding:28px}nav{display:flex;gap:22px;flex-wrap:wrap;padding:12px 0;border-bottom:1px solid #d9e2eb}a{color:#1769aa}nav a{text-decoration:none;padding:4px}nav a[aria-current]{font-weight:700;border-bottom:3px solid #1769aa}h1{font-size:27px}h2{font-size:18px;margin-top:0}h3{font-size:14px}section,details{background:white;border:1px solid #dce4ec;border-radius:7px;padding:22px;margin:18px 0}.eyebrow{font-size:11px;color:#697a8c;text-transform:uppercase;letter-spacing:.07em}header p{color:#657689}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.metrics section{margin:0}.metrics h2{font-size:12px;color:#637689}.metrics strong{font-size:24px}.columns{display:grid;grid-template-columns:1fr 1fr;gap:20px}.error{background:#fff0f0;color:#963838}label{display:block;font-weight:600;margin:13px 0}input:not([type=hidden]),select,textarea{display:block;width:100%;max-width:620px;border:1px solid #cbd7e3;border-radius:4px;padding:10px;font:inherit;margin-top:5px}.check input[type=checkbox]{display:inline;width:auto;margin-right:7px}button{background:#1769aa;color:white;border:0;border-radius:4px;padding:12px 18px;cursor:pointer;font:600 14px system-ui}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:11px 9px;border-bottom:1px solid #e2e9f0}th{font-size:12px;color:#65778a}summary{cursor:pointer;font-weight:600}dd{overflow-wrap:anywhere}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #dea43a;outline-offset:2px}@media(max-width:800px){main{padding:15px}.metrics{grid-template-columns:1fr 1fr}.columns{grid-template-columns:1fr}section{overflow:auto}}@media(max-width:480px){.metrics{grid-template-columns:1fr}}';}
}
